local CraneMaker = {}
local PRODUCTS = {
    simple_wood_crane = { name = "Preprost lesen žerjav", woodCost = 5, ropeCost = 2, ironCost = 1, time = 6, cost = 200, science = 18, happiness = 1, description = "Preprost lesen žerjav za gradnjo." },
    iron_reinforced_crane = { name = "Železnookrepljen žerjav", woodCost = 4, ironCost = 3, ropeCost = 2, time = 9, cost = 480, science = 32, happiness = 2, prestige = 2, description = "Železnookrepljen žerjav za trgovce." },
    silver_pulley_crane = { name = "Srebrnanični žerjav", woodCost = 4, ironCost = 2, silverCost = 1, ropeCost = 2, time = 13, cost = 1100, science = 48, happiness = 2, prestige = 6, description = "Srebrnanični žerjav za plemiče." },
    gold_trimmed_crane = { name = "Zlatookrasni žerjav", woodCost = 4, ironCost = 2, goldCost = 1, silverCost = 1, ropeCost = 2, time = 17, cost = 2500, science = 62, happiness = 3, prestige = 14, description = "Zlatookrasni žerjav za visoke plemiče." },
    jewel_set_crane = { name = "Draguljasta žerjav", woodCost = 4, ironCost = 2, goldCost = 1, silverCost = 1, ropeCost = 2, jewelCost = 1, time = 21, cost = 5200, science = 78, happiness = 5, prestige = 27, description = "Žerjav z draguljem za visoko plemstvo." },
    royal_grand_crane = { name = "Kraljevski veliki žerjav", woodCost = 6, ironCost = 3, goldCost = 2, silverCost = 2, ropeCost = 2, jewelCost = 2, pearlCost = 2, time = 28, cost = 11000, science = 95, happiness = 12, prestige = 58, description = "Veliki kraljevski žerjav z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    crane_workshop = { name = "Žerjavna delavnica", cost = { gold = 320, wood = 180, stone = 140, iron = 6 }, upkeep = 7, qualityBonus = 5 },
    machinery_loft = { name = "Strojna podstrešje", cost = { gold = 1100, wood = 320, stone = 280, silver = 6, rope = 6 }, upkeep = 26, qualityBonus = 18 },
    master_engineer_atelier = { name = "Mojstrski inženirski atelje", cost = { gold = 2900, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 68, qualityBonus = 30 },
    royal_engineering_palace = { name = "Kraljevska inženirska palača", cost = { gold = 12500, wood = 600, stone = 800, gold = 80, jewel = 18 }, upkeep = 250, qualityBonus = 55, prestigeBonus = 50 },
}
CraneMaker.woodStock = 22; CraneMaker.ironStock = 14; CraneMaker.ropeStock = 12; CraneMaker.silverStock = 6; CraneMaker.goldStock = 6; CraneMaker.jewelStock = 4; CraneMaker.pearlStock = 4
CraneMaker.productStock = {}; CraneMaker.buildings = {}; CraneMaker.maker = nil; CraneMaker.activeMaking = {}; CraneMaker.totalProducts = 0; CraneMaker.dayTimer = 0
function CraneMaker.init() CraneMaker.woodStock=22; CraneMaker.ironStock=14; CraneMaker.ropeStock=12; CraneMaker.silverStock=6; CraneMaker.goldStock=6; CraneMaker.jewelStock=4; CraneMaker.pearlStock=4; CraneMaker.productStock={}; CraneMaker.buildings={}; CraneMaker.maker=nil; CraneMaker.activeMaking={}; CraneMaker.totalProducts=0; CraneMaker.dayTimer=0; print("[CraneMaker] Royal Crane Maker System initialized (6 products, 4 buildings)") end
function CraneMaker.hireMaker(n,s) s=s or math.random(55,90); local c=600+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CraneMaker.maker={name=n or ("Žerjavar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žerjavar najet: %s (spretnost: %d)",CraneMaker.maker.name,s),"success") end; return true end
function CraneMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CraneMaker.build(id) local ok,e=CraneMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CraneMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CraneMaker.getQualityBonus() local b=0; for _,bd in ipairs(CraneMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CraneMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and CraneMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and CraneMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.ropeCost and CraneMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.silverCost and CraneMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CraneMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CraneMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CraneMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CraneMaker.buildings==0 then return false,"Potrebna žerjavna delavnica" end; if not CraneMaker.maker then return false,"Potreben žerjavar" end; return true end
function CraneMaker.make(pt,qty) qty=qty or 1; local ok,e=CraneMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then CraneMaker.woodStock=CraneMaker.woodStock-d.woodCost*qty end; if d.ironCost then CraneMaker.ironStock=CraneMaker.ironStock-d.ironCost*qty end; if d.ropeCost then CraneMaker.ropeStock=CraneMaker.ropeStock-d.ropeCost*qty end; if d.silverCost then CraneMaker.silverStock=CraneMaker.silverStock-d.silverCost*qty end; if d.goldCost then CraneMaker.goldStock=CraneMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CraneMaker.jewelStock=CraneMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CraneMaker.pearlStock=CraneMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CraneMaker.maker then t=math.max(1,t-math.floor(CraneMaker.maker.skill/12)) end; table.insert(CraneMaker.activeMaking,{id="crane_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CraneMaker.completeMaking(m) local q=1.0+(CraneMaker.getQualityBonus()/100); if CraneMaker.maker then q=q+(CraneMaker.maker.skill/140) end; q=math.min(2.5,q); CraneMaker.productStock[m.productType]=(CraneMaker.productStock[m.productType] or 0)+m.quantity; CraneMaker.totalProducts=CraneMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CraneMaker.maker then CraneMaker.maker.itemsMade=CraneMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CraneMaker.maker.skill=math.min(100,CraneMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žerjav izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"crane.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function CraneMaker.update(dt) if not _G.state then return end; CraneMaker.dayTimer=CraneMaker.dayTimer+dt; if CraneMaker.dayTimer>=30 then CraneMaker.dayTimer=0; for i=#CraneMaker.activeMaking,1,-1 do local m=CraneMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CraneMaker.completeMaking(m); table.remove(CraneMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CraneMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CraneMaker.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CraneMaker.getStats() return {woodStock=CraneMaker.woodStock,ironStock=CraneMaker.ironStock,ropeStock=CraneMaker.ropeStock,silverStock=CraneMaker.silverStock,goldStock=CraneMaker.goldStock,jewelStock=CraneMaker.jewelStock,pearlStock=CraneMaker.pearlStock,productStock=CraneMaker.productStock,numBuildings=#CraneMaker.buildings,hasMaker=CraneMaker.maker~=nil,makerName=CraneMaker.maker and CraneMaker.maker.name or "—",makerSkill=CraneMaker.maker and CraneMaker.maker.skill or 0,activeMaking=#CraneMaker.activeMaking,totalProducts=CraneMaker.totalProducts} end
return CraneMaker
